tool_calls:
cd /src 2>/dev/null || { echo "no /src"; exit 1; }
python3 - <<'EOF'
import os
n=0
for r,d,fs in os.walk('/src'):
    for f in fs:
        if f.endswith('.js'):
            p=os.path.join(r,f)
            try:
                s=open(p,encoding='utf-8',newline='').read()
            except Exception as e:
                print("skip",p,e); continue
            c=s.count('console.log')
            if c:
                open(p,'w',encoding='utf-8',newline='').write(s.replace('console.log','logger.info'))
                print(f"{p}: {c} replacements"); n+=1
print(f"Files modified: {n}")
EOF

